# The mutations of Wolly.Query, sourced by scripts/mutate.sh and
# scripts/mutate-target.sh.
mutations+=(
	"Query.hiq|s/constant queryMost: Index := 1024;/constant queryMost: Index := 1025;/|a query of 1025 bytes"
	"Query.hiq|s/constant depthMost: Index := 16;/constant depthMost: Index := 17;/|17 levels of nesting"
	"Query.hiq|s/if depth > depthMost then/if depth >= depthMost then/|16 levels of nesting are refused"
	"Query.hiq|s/constant nodesMost: Index := 64;/constant nodesMost: Index := 65;/|65 nodes"
	"Query.hiq|s/constant wordsMost: Index := 16;/constant wordsMost: Index := 17;/|17 words in quotes"
	"Query.hiq|s/constant wordBytesMost: Index := 64;/constant wordBytesMost: Index := 65;/|a word of 65 bytes"
	"Query.hiq|s/\"body : /\"/|text in quotes is searched in the host, source and level too"
	"Query.hiq|s/        writeByte(\&!out, '\"');/        skip;/|the phrase of FTS5 is not closed"
	"Query.hiq|s/                if isControl(text\[i\]) then/                if false then/|a control byte in quotes"
	"Query.hiq|s/            return validHostname(value);/            return true;/|a host that is no host name"
	"Query.hiq|s/                if not fitsPrefix(field, prefix) then/                if false then/|any prefix"
	"Query.hiq|s/                byte := byte + 32;/                skip;/|keywords and fields only in small letters"
	"Query.hiq|s/            return token.start - 1;/            return token.start;/|the position of a value in quotes is past its quote"
	"Query.hiq|s/if isWordByte(text\[i\]) and (not dotsAt(text, i)) then/if isWordByte(text[i]) then/|two dots end no word"
	"Query.hiq|s/        return not (isDigit(byte) or isLetter(byte));/        return false;/|punctuation is a word"
	"Query.hiq|s/                return 29;/                return 28;/|no leap day"
	"Query.hiq|s/if upper and time.wholeDay then/if false then/|a day as the end of a range is its first second"
	"Query.hiq|s/AND at <= ? AND at >= ? AND at <= ?\";/AND at <= ? AND at > ? AND at <= ?\";/|a range of time without its start"
	"Query.hiq|s/wide(node.stop - node.start);/wide((node.stop - node.start) + 1);/|a prefix one byte too long"
	"Query.hiq|s/WHERE at >= ? AND at <= ? EXCEPT SELECT/WHERE at >= ? AND at <= ? UNION SELECT/|not is all lines"
	"Query.hiq|s/WHERE node = ? INTERSECT SELECT/WHERE node = ? UNION SELECT/|and is or"
	"Query.hiq|s/        storeNth(\&!joined, count - 1, true);/        skip;/|no time window"
	"Query.hiq|s/                if node.kind = andNode then/                if (node.kind = andNode) or (node.kind = orNode) then/|a time under or narrows the window"
	"Query.hiq|s/                if lines > mostLines then/                if lines >= mostLines then/|as many lines as allowed are too many"
	"Query.hiq|s/ORDER BY l.at DESC, l.id DESC/ORDER BY l.at, l.id/|oldest first"
	"Query.hiq|s/constant textsMost: Index := 8;/constant textsMost: Index := 9;/|nine texts in quotes"
	"Query.hiq|s/ AND hilde_search.title = l.host || ' ' || l.source || ' ' || l.level//|a document of another part under the key of a line"
	"Query.hiq|s/AND lower(host) = lower(?)/AND host = ?/|a host only in the case it was kept"
	"Query.hiq|s/substr(CAST(lower(host) AS BLOB), 1, ?) = CAST(lower(?) AS BLOB)/substr(CAST(host AS BLOB), 1, ?) = CAST(? AS BLOB)/|a prefix of a host only in its case"
	"Query.hiq|s/                if node.kind = andNode then/                if (node.kind = andNode) or (node.kind = notNode) then/|a time under not narrows the window"
	"Query.hiq|s/high), node.low), node.high)));/high), node.high), node.low)));/|the bounds of a range bound the other way round"
	"Query.hiq|s/((byte = '\/') or (byte = '@'))/(byte = '@')/|a slash ends a word"
)
